import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function ReviewGame({ user }) {
  const [games, setGames] = useState([]);
  const [selectedGame, setSelectedGame] = useState('');
  const [rating, setRating] = useState(5);
  const [reviewText, setReviewText] = useState('');
  const [msg, setMsg] = useState({ type: '', text: '' });
  const [myReviews, setMyReviews] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(`${API}/games`).then(r => r.json()).then(d => setGames(Array.isArray(d) ? d : d.games || [])).catch(() => {});
    fetchMyReviews();
  }, []);

  const fetchMyReviews = async () => {
    try {
      const res = await fetch(`${API}/reviews/user/${user.userID || user.id}`);
      const data = await res.json();
      setMyReviews(Array.isArray(data) ? data : []);
    } catch { setMyReviews([]); }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg({ type: '', text: '' });
    setLoading(true);
    try {
      const res = await fetch(`${API}/reviews`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.userID || user.id,
          gameId: selectedGame,
          rating,
          reviewText
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || data.error || 'Failed');
      setMsg({ type: 'success', text: 'Review submitted!' });
      setSelectedGame(''); setRating(5); setReviewText('');
      fetchMyReviews();
    } catch (err) {
      setMsg({ type: 'error', text: err.message });
    }
    setLoading(false);
  };

  const handleDelete = async (reviewId) => {
    try {
      const res = await fetch(`${API}/reviews/review/${reviewId}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete');
      setMsg({ type: 'success', text: 'Review deleted.' });
      fetchMyReviews();
    } catch (err) {
      setMsg({ type: 'error', text: err.message });
    }
  };

  return (
    <div>
      <h2 style={heading}>Leave a Review</h2>

      {msg.text && <p style={{ color: msg.type === 'success' ? '#00ff88' : '#fc8181', marginBottom: '1rem' }}>{msg.text}</p>}

      <div style={card}>
        <form onSubmit={handleSubmit}>
          <div style={formGroup}>
            <label style={label}>Select Game</label>
            <select style={select} value={selectedGame} onChange={e => setSelectedGame(e.target.value)} required>
              <option value="">-- Choose a game --</option>
              {games.map((g, i) => <option key={g.gameID || i} value={g.gameID || g.id}>{g.title || g.name}</option>)}
            </select>
          </div>
          <div style={formGroup}>
            <label style={label}>Rating</label>
            <div style={{ display: 'flex', gap: '0.5rem' }}>
              {[1, 2, 3, 4, 5].map(n => (
                <span key={n} onClick={() => setRating(n)}
                  style={{ fontSize: '1.5rem', cursor: 'pointer', color: n <= rating ? '#ffd700' : '#444' }}>
                  ★
                </span>
              ))}
            </div>
          </div>
          <div style={formGroup}>
            <label style={label}>Review</label>
            <textarea style={{ ...select, height: 90, resize: 'vertical' }}
              placeholder="Write your review..."
              value={reviewText}
              onChange={e => setReviewText(e.target.value)}
              required
            />
          </div>
          <button type="submit" style={primaryBtn} disabled={loading}>{loading ? 'Submitting...' : 'Submit Review'}</button>
        </form>
      </div>

      <h3 style={{ ...heading, marginTop: '2rem' }}>My Reviews</h3>
      {myReviews.length === 0
        ? <p style={{ color: '#aaa' }}>No reviews yet.</p>
        : myReviews.map((r, i) => (
          <div key={r.reviewID || i} style={reviewCard}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div>
                <strong style={{ color: '#fff' }}>{r.gameTitle || r.title || `Game #${r.gameID}`}</strong>
                <span style={{ marginLeft: '0.75rem', color: '#ffd700' }}>{'★'.repeat(r.rating)}{'☆'.repeat(5 - r.rating)}</span>
              </div>
              <button onClick={() => handleDelete(r.reviewID || r.id)}
                style={{ background: 'none', border: '1px solid #555', color: '#aaa', borderRadius: 6, padding: '0.25rem 0.6rem', cursor: 'pointer', fontSize: '0.8rem' }}>
                Delete
              </button>
            </div>
            <p style={{ color: '#bbb', marginTop: '0.5rem', fontSize: '0.9rem' }}>{r.reviewText}</p>
          </div>
        ))}
    </div>
  );
}

const heading = { color: '#fff', marginBottom: '1rem' };
const card = { background: '#1a1a2e', padding: '1.5rem', borderRadius: 12, marginBottom: '1.5rem', maxWidth: 500 };
const formGroup = { marginBottom: '1rem' };
const label = { display: 'block', color: '#aaa', fontSize: '0.85rem', marginBottom: '0.4rem' };
const select = { width: '100%', padding: '0.6rem 1rem', background: '#0f0f1a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: '0.9rem' };
const primaryBtn = { width: '100%', padding: '0.65rem', background: '#a855f7', color: '#fff', border: 'none', borderRadius: 8, fontWeight: 700, cursor: 'pointer', fontSize: '0.95rem' };
const reviewCard = { background: '#1a1a2e', border: '1px solid #333', borderRadius: 10, padding: '1rem', marginBottom: '0.75rem' };

export default ReviewGame;
